import{_ as e,c as t,a2 as i,o as l}from"./chunks/framework.D7kq4b6j.js";const r="/VitePressSite/assets/Pasted%20image%2020240725144605.DKYPLOje.png",o="/VitePressSite/assets/Pasted%20image%2020240725145637.DHnKZpkj.png",_=JSON.parse('{"title":"音调","description":"","frontmatter":{},"headers":[],"relativePath":"docs/日本語学習/五十音/5-音调.md","filePath":"docs/日本語学習/五十音/5-音调.md","lastUpdated":1721892855000}'),s={name:"docs/日本語学習/五十音/5-音调.md"};function n(d,a,c,h,p,m){return l(),t("div",null,a[0]||(a[0]=[i('<h1 id="音调" tabindex="-1">音调 <a class="header-anchor" href="#音调" aria-label="Permalink to &quot;音调&quot;">​</a></h1><h2 id="特征" tabindex="-1">特征 <a class="header-anchor" href="#特征" aria-label="Permalink to &quot;特征&quot;">​</a></h2><p>日语的发音有2个特征：一是<strong>单峰型</strong>，没有多次起伏。二是<strong>前2个假名音调一定相反</strong>：第一个高，第二个就低；相反，第一个低，第二个就高。明白了这2个特征，加上单词发音的规则，那么就可以发音读单词了。</p><h2 id="低音" tabindex="-1">低音 <a class="header-anchor" href="#低音" aria-label="Permalink to &quot;低音&quot;">​</a></h2><p>接近于拼音第三声 ǎ</p><h2 id="高音" tabindex="-1">高音 <a class="header-anchor" href="#高音" aria-label="Permalink to &quot;高音&quot;">​</a></h2><p>接近于拼音第一声 ā</p><h2 id="类型" tabindex="-1">类型 <a class="header-anchor" href="#类型" aria-label="Permalink to &quot;类型&quot;">​</a></h2><ul><li>0️⃣型：单词不论是几个音节（最少是1个音节），从低音入手，第二拍升高，一直到读到最后拍节也不下降。</li><li>1️⃣型：单词不论是几个音节（最少是1个音节），从高音入手，第二拍下降，一直到读到最后拍节也不上升。</li><li>2️⃣型：单词不论是几个音节（最少是2个音节），从低音入手，第二拍升高，第三拍下降读到最后拍节也不上升。</li><li>3️⃣型：单词不论是几个音节（最少是3个音节），从低音入手，第二拍升高，第三拍保持，第四拍下降，读到最后拍节也不上升。</li><li>4️⃣型：单词不论是几个音节（最少是4个音节），从低音入手，第二拍升高，保持到第四拍，第五拍下降，读到最后拍节也不上升。</li><li>5️⃣型：单词不论是几个音节（最少是5个音节），从低音入手，第二拍升高，保持到第五拍，第六拍下降，读到最后拍节也不上升。</li><li>6️⃣型：单词不论是几个音节（最少是6个音节），从低音入手，第二拍升高，保持到第六拍，第七拍下降，读到最后拍节也不上升。 <img src="'+r+'" alt=""></li></ul><p>Tip:</p><blockquote><p>0 调：311111 1 调：133333 2 调：313333 3 调：311333 4 调：311133 5 调：311113</p></blockquote><h2 id="标注方式" tabindex="-1">标注方式 <a class="header-anchor" href="#标注方式" aria-label="Permalink to &quot;标注方式&quot;">​</a></h2><ul><li>数字式</li><li>划线式</li><li>粗体式 <img src="'+o+'" alt=""></li></ul><p>更多 <a href="https://medium.com/ken-m-lai/%E6%97%A5%E8%AF%AD%E5%8D%95%E8%AF%8D%E7%9A%84%E9%9F%B3%E8%B0%83-c15772edead3" target="_blank" rel="noreferrer">https://medium.com/ken-m-lai/日语单词的音调-c15772edead3</a></p>',14)]))}const f=e(s,[["render",n]]);export{_ as __pageData,f as default};
